unsafe fn translate_encoder_to_transmitter(encoder: graphics_object_id) -> transmitter { match encoder.id { ENCODER_ID_INTERNAL_UNIPHY => match encoder.enum_id { ENUM_ID_1=>TRANSMITTER_UNIPHY_A, ENUM_ID_2=>TRANSMITTER_UNIPHY_B, _=>TRANSMITTER_UNKNOWN }, ENCODER_ID_INTERNAL_UNIPHY1=>match encoder.enum_id { ENUM_ID_1=>TRANSMITTER_UNIPHY_C, ENUM_ID_2=>TRANSMITTER_UNIPHY_D, _=>TRANSMITTER_UNKNOWN }, ENCODER_ID_INTERNAL_UNIPHY2=>match encoder.enum_id { ENUM_ID_1=>TRANSMITTER_UNIPHY_E, ENUM_ID_2=>TRANSMITTER_UNIPHY_F, _=>TRANSMITTER_UNKNOWN }, ENCODER_ID_INTERNAL_UNIPHY3=>match encoder.enum_id { ENUM_ID_1=>TRANSMITTER_UNIPHY_G, _=>TRANSMITTER_UNKNOWN }, _=>TRANSMITTER_UNKNOWN } }
unsafe fn encoder_is_external_dp(e: graphics_object_id) -> bool { matches!(e.id, ENCODER_ID_EXTERNAL_NUTMEG | ENCODER_ID_EXTERNAL_TRAVIS) }

unsafe fn link_destruct(link: *mut dc_link) { if !(*link).ddc.is_null(){link_destroy_ddc_service(&mut (*link).ddc)}; if !(*link).panel_cntl.is_null(){((*(*link).panel_cntl).funcs).destroy(&mut (*link).panel_cntl)}; if !(*link).link_enc.is_null() && !(*link).is_dig_mapping_flexible { if (*link).link_id.id != CONNECTOR_ID_VIRTUAL && (*link).eng_id != ENGINE_ID_UNKNOWN { (*(*(*link).dc).res_pool).link_encoders[(*link).eng_id-ENGINE_ID_DIGA]=core::ptr::null_mut(); (*(*link).dc).res_pool.dig_link_enc_count-=1; } ((*(*link).link_enc).funcs).destroy(&mut (*link).link_enc); }; if !(*link).hpo_frl_link_enc.is_null(){((*(*link).hpo_frl_link_enc).funcs).destroy(&mut (*link).hpo_frl_link_enc)}; if !(*link).local_sink.is_null(){dc_sink_release((*link).local_sink)}; for i in 0..(*link).sink_count { dc_sink_release((*link).remote_sinks[i]); } }

unsafe fn get_ddc_line(link: *mut dc_link) -> channel_id { if (*link).force_to_use_aux { (*link).aux_hw_inst+1 } else { let ddc=get_ddc_pin((*link).ddc); if ddc.is_null(){CHANNEL_ID_UNKNOWN}else{match dal_ddc_get_line(ddc){GPIO_DDC_LINE_DDC1=>CHANNEL_ID_DDC1,GPIO_DDC_LINE_DDC2=>CHANNEL_ID_DDC2,GPIO_DDC_LINE_DDC3=>CHANNEL_ID_DDC3,GPIO_DDC_LINE_DDC4=>CHANNEL_ID_DDC4,GPIO_DDC_LINE_DDC5=>CHANNEL_ID_DDC5,GPIO_DDC_LINE_DDC6=>CHANNEL_ID_DDC6,GPIO_DDC_LINE_DDC_VGA=>CHANNEL_ID_DDC_VGA,GPIO_DDC_LINE_I2C_PAD=>CHANNEL_ID_I2C_PAD,_=>{BREAK_TO_DEBUGGER();CHANNEL_ID_UNKNOWN}}}} }

unsafe fn find_analog_engine(link: *mut dc_link, enc: *mut graphics_object_id) -> engine_id { for i in 0..3 { if (*(*(*link).ctx).dc_bios).funcs.get_src_obj((*link).ctx.dc_bios,(*link).link_id,i,enc)!=BP_RESULT_OK{return ENGINE_ID_UNKNOWN}; match (*enc).id { ENCODER_ID_INTERNAL_DAC1|ENCODER_ID_INTERNAL_KLDSCP_DAC1=>return ENGINE_ID_DACA, ENCODER_ID_INTERNAL_DAC2|ENCODER_ID_INTERNAL_KLDSCP_DAC2=>return ENGINE_ID_DACB, _=>{} } } *enc=core::mem::zeroed(); ENGINE_ID_UNKNOWN }
unsafe fn analog_engine_supported(e: engine_id)->bool { e==ENGINE_ID_DACA || e==ENGINE_ID_DACB }

