unsafe fn construct_phy(link: *mut dc_link, init_params: *const link_init_data) -> bool { let _=link; let _=init_params; /* external BIOS/resource operations are supplied by linked headers */ todo!("direct translation requires external C ABI declarations") }
unsafe fn construct_dpia(link: *mut dc_link, init_params: *const link_init_data) -> bool { let _=link; let _=init_params; todo!("direct translation requires external C ABI declarations") }
unsafe fn link_construct(link: *mut dc_link, p: *const link_init_data)->bool { if (*p).is_dpia_link {construct_dpia(link,p)} else {construct_phy(link,p)} }
pub unsafe fn link_create(p: *const link_init_data)->*mut dc_link { let link=kzalloc_obj::<dc_link>(); if link.is_null(){return core::ptr::null_mut()} if !link_construct(link,p){kfree(link);return core::ptr::null_mut()} link }
pub unsafe fn link_destroy(link: *mut *mut dc_link) { link_destruct(*link); kfree(*link); *link=core::ptr::null_mut(); }

